def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float | None = None,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    if scaling is None:
        scaling = query.size(-1) ** -0.5

    # Take the dot product between "query" and "key" to get the raw attention scores.
    attn_weights = torch.matmul(query, key.transpose(2, 3)) * scaling

    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)

    attn_output = torch.matmul(attn_weights, value)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class MiniCPMO2_6CrossAttention(nn.Module):
    """
    Multi-headed cross-attention, as in DETR: keys can get position embeddings, values never do. The resampler adds the
    slice's 2D position embedding to the keys only.
    """

    def __init__(
        self,
        config: MiniCPMO2_6Config,
        hidden_size: int,
        num_attention_heads: int,
        dropout: float = 0.0,
        bias: bool = True,
    ):
        super().__init__()
        self.config = config
        self.head_dim = hidden_size // num_attention_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = dropout
        self.is_causal = False

        self.k_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.v_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.q_proj = nn.Linear(hidden_size, hidden_size, bias=bias)
        self.o_proj = nn.Linear(hidden_size, hidden_size, bias=bias)

    def forward(
        self,
        hidden_states: torch.Tensor,
        key_value_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        position_embeddings: torch.Tensor | None = None,
        encoder_position_embeddings: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Position embeddings logic:
        - Queries get position_embeddings
        - Keys get encoder_position_embeddings
        - Values don't get any position embeddings
        """
        query_input_shape = hidden_states.shape[:-1]
        query_hidden_shape = (*query_input_shape, -1, self.head_dim)

        kv_input_shape = key_value_states.shape[:-1]
        kv_hidden_shape = (*kv_input_shape, -1, self.head_dim)

        query_input = hidden_states + position_embeddings if position_embeddings is not None else hidden_states
        key_input = (
            key_value_states + encoder_position_embeddings
            if encoder_position_embeddings is not None
            else key_value_states
        )

        query_states = self.q_proj(query_input).view(query_hidden_shape).transpose(1, 2)
        key_states = self.k_proj(key_input).view(kv_hidden_shape).transpose(1, 2)
        value_states = self.v_proj(key_value_states).view(kv_hidden_shape).transpose(1, 2)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            **kwargs,
        )

        attn_output = attn_output.reshape(*query_input_shape, -1).contiguous()
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class MiniCPMO2_6PositionEmbedding(nn.Module):
    """
    2D sin-cos embedding of `(row, col)` patch positions, added to the resampler's keys. Uses the axial rope frequencies
    (the same for rows and columns), laid out as [sin_col | cos_col | sin_row | cos_row] like the original.
    """

    def __init__(self, embed_dim: int, theta: float = 10000.0):
        super().__init__()
        self.embed_dim = embed_dim
        self.theta = theta
        self.inv_freq = nn.Buffer(self.compute_inv_freq(embed_dim, theta), persistent=False)

    @staticmethod
    def compute_inv_freq(embed_dim: int, theta: float) -> torch.Tensor:
        spatial_dim = embed_dim // 2
        return 1.0 / (theta ** (torch.arange(0, spatial_dim, 2, dtype=torch.float) / spatial_dim))

    def forward(self, patch_position_ids: torch.Tensor) -> torch.Tensor:
        inv_freq = self.inv_freq.to(patch_position_ids.device)
        row_angles = patch_position_ids[..., 0, None].float() * inv_freq
        col_angles = patch_position_ids[..., 1, None].float() * inv_freq
        return torch.cat([col_angles.sin(), col_angles.cos(), row_angles.sin(), row_angles.cos()], dim=-1)


class MiniCPMO2_6Resampler(nn.Module):
    """
    Perceiver-style resampler: `resampler_n_latents` learned queries cross-attend to the patch features of one image
    slice, so every slice becomes `resampler_n_latents` tokens at the language model's width. Keys get a 2D sin-cos
    position embedding of the slice's patch grid; values do not.
    """

    def __init__(self, config: MiniCPMO2_6Config):
        super().__init__()
        self.config = config
        self.embed_dim = config.text_config.hidden_size
        self.query = nn.Parameter(torch.zeros(config.resampler_n_latents, self.embed_dim))
        self.kv_proj = nn.Linear(config.vision_config.hidden_size, self.embed_dim, bias=False)
        self.ln_q = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.ln_kv = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.attn = MiniCPMO2_6CrossAttention(config, self.embed_dim, config.resampler_n_heads)
        self.ln_post = nn.LayerNorm(self.embed_dim, eps=1e-6)
        self.proj = nn.Parameter(torch.zeros(self.embed_dim, self.embed_dim))
        self.position_embedding = MiniCPMO2_6PositionEmbedding(self.embed_dim)

    def forward(
        self,
        vision_features: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        key_value_states = self.kv_proj(vision_features)
        key_value_states = self.ln_kv(key_value_states)

        # Position embeddings of the real patches only (padding gets none)
        position_embeddings = self.position_embedding(patch_position_ids)
        position_embeddings = position_embeddings * pixel_attention_mask[..., None]
        position_embeddings = position_embeddings.to(key_value_states.dtype)

        # The same learned queries for every slice
        num_slices = key_value_states.shape[0]
        query_states = self.ln_q(self.query)
        query_states = query_states.unsqueeze(0).expand(num_slices, -1, -1)

        attention_mask = create_bidirectional_mask(
            config=self.config,
            inputs_embeds=query_states,
            attention_mask=pixel_attention_mask,
            encoder_hidden_states=key_value_states,
        )
        attention_output, _ = self.attn(
            query_states,
            key_value_states,
            attention_mask=attention_mask,
            encoder_position_embeddings=position_embeddings,
            **kwargs,
        )
        resampled_features = self.ln_post(attention_output) @ self.proj
        return resampled_features


@auto_docstring
class MiniCPMO2_6PreTrainedModel(PreTrainedModel):
    config: MiniCPMO2_6Config
    base_model_prefix = "model"
    input_modalities = ("image", "audio", "text")
    supports_gradient_checkpointing = True

    _supports_flash_attn = True
    _supports_sdpa = True

    _can_compile_fullgraph = True
    _supports_flex_attn = True
    _supports_attention_backend = True
    # Sub-models add their own no-split layers
    _no_split_modules = ["MiniCPMO2_6Resampler"]
    # The checkpoint also holds the speech decoder (`tts.*`), which this model doesn't include
    _keys_to_ignore_on_load_unexpected = [r"^tts\."]

    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, MiniCPMO2_6Resampler):
            init.trunc_normal_(module.query, std=0.02)
            init.normal_(module.proj, std=module.embed_dim**-0.5)
        elif isinstance(module, MiniCPMO2_6PositionEmbedding):
            init.copy_(module.inv_freq, module.compute_inv_freq(module.embed_dim, module.theta))


class MiniCPMO2_6AudioAttention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(
        self,
        embed_dim: int,
        num_heads: int,
        dropout: float = 0.0,
        is_decoder: bool = False,
        bias: bool = True,
        is_causal: bool = False,
        layer_idx: int | None = None,
        config: MiniCPMO2_6Config | None = None,
    ):
        super().__init__()
        self.embed_dim = embed_dim
        self.num_heads = num_heads
        self.dropout = dropout
        self.head_dim = embed_dim // num_heads
        self.config = config

        if (self.head_dim * num_heads) != self.embed_dim:
            raise ValueError(
                f"embed_dim must be divisible by num_heads (got `embed_dim`: {self.embed_dim}"
                f" and `num_heads`: {num_heads})."
            )
        self.scaling = self.head_dim**-0.5
        self.is_decoder = is_decoder
        self.is_causal = is_causal

        if layer_idx is None and is_decoder:
            logger.warning_once(
                f"Instantiating a decoder {self.__class__.__name__} without passing `layer_idx` is not recommended and "
                "will to errors during the forward call, if caching is used. Please make sure to provide a `layer_idx` "
                "when creating this class."
            )
        self.layer_idx = layer_idx

        self.k_proj = nn.Linear(embed_dim, embed_dim, bias=False)
        self.v_proj = nn.Linear(embed_dim, embed_dim, bias=bias)
        self.q_proj = nn.Linear(embed_dim, embed_dim, bias=bias)
        self.out_proj = nn.Linear(embed_dim, embed_dim, bias=bias)

    def _shape(self, tensor: torch.Tensor, seq_len: int, bsz: int):
        return tensor.view(bsz, seq_len, self.num_heads, self.head_dim).transpose(1, 2).contiguous()

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        output_attentions: bool = False,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor | None, tuple[torch.Tensor] | None]:
        """Input shape: Batch x Time x Channel"""

        bsz, tgt_len, _ = hidden_states.size()

        # Scaling is susceptible to floating point arithmetics' imprecisions
        # which can lead to different results (this is dependent from model
        # to model, e.g. whisper is one such case). We therefore keep the
        # original order of scaling to follow the original implementation
        # and enforce no scaling (1.0) in the attention call below.
        query_states = self._shape(self.q_proj(hidden_states) * self.scaling, tgt_len, bsz)
        key_states = self._shape(self.k_proj(hidden_states), -1, bsz)
        value_states = self._shape(self.v_proj(hidden_states), -1, bsz)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.dropout,
            scaling=1.0,
            output_attentions=output_attentions,
            **kwargs,
        )

        attn_output = attn_output.reshape(bsz, tgt_len, -1).contiguous()
        attn_output = self.out_proj(attn_output)

        return attn_output, attn_weights


class MiniCPMO2_6AudioEncoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: MiniCPMO2_6AudioConfig):
        super().__init__()
        self.embed_dim = config.d_model
        self.self_attn = MiniCPMO2_6AudioAttention(
            embed_dim=self.embed_dim,
            num_heads=config.num_attention_heads,
            dropout=config.attention_dropout,
            config=config,
        )
        self.self_attn_layer_norm = nn.LayerNorm(self.embed_dim)
        self.dropout = config.dropout
        self.activation_fn = ACT2FN[config.activation_function]
        self.activation_dropout = config.activation_dropout
        self.fc1 = nn.Linear(self.embed_dim, config.encoder_ffn_dim)
        self.fc2 = nn.Linear(config.encoder_ffn_dim, self.embed_dim)
        self.final_layer_norm = nn.LayerNorm(self.embed_dim)

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor`): input to the layer of shape `(batch, seq_len, embed_dim)`
            attention_mask (`torch.Tensor`): attention mask of size
                `(batch, 1, tgt_len, src_len)` where padding elements are indicated by very large negative values.
        """
        residual = hidden_states
        hidden_states = self.self_attn_layer_norm(hidden_states)
        hidden_states, _ = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            **kwargs,
        )
        hidden_states = nn.functional.dropout(hidden_states, p=self.dropout, training=self.training)
        hidden_states = residual + hidden_states

        residual = hidden_states
        hidden_states = self.final_layer_norm(hidden_states)
        hidden_states = self.activation_fn(self.fc1(hidden_states))
        hidden_states = nn.functional.dropout(hidden_states, p=self.activation_dropout, training=self.training)
        hidden_states = self.fc2(hidden_states)
        hidden_states = nn.functional.dropout(hidden_states, p=self.dropout, training=self.training)
        hidden_states = residual + hidden_states

        if hidden_states.dtype == torch.float16:
            clamp_value = torch.finfo(hidden_states.dtype).max - 1000
            hidden_states = torch.clamp(hidden_states, min=-clamp_value, max=clamp_value)

        return hidden_states


def chunked_limited_mask_function(left_ctx: int, right_ctx: int) -> Callable:
    """
    `chunked_limited` attention mask.
    """
    chunk_size = right_ctx + 1
    left_context_chunks = left_ctx // chunk_size if left_ctx >= 0 else 10_000

    def inner_mask(batch_idx: int, head_idx: int, q_idx: int, kv_idx: int) -> bool:
        q_chunk = torch.div(q_idx, chunk_size, rounding_mode="trunc")
        kv_chunk = torch.div(kv_idx, chunk_size, rounding_mode="trunc")
        chunk_diff = q_chunk - kv_chunk
        return (chunk_diff >= 0) & (chunk_diff <= left_context_chunks)

    return inner_mask


@auto_docstring(
    custom_intro="""
    The audio encoder of MiniCPM-o 2.6, without any head or projection on top.
    """
)
class MiniCPMO2_6AudioEncoder(MiniCPMO2_6PreTrainedModel):
    """
    Whisper encoder over up to 30 s of audio per row; each frame attends to its own 1 s chunk and to all earlier ones.
    """

    config: MiniCPMO2_6AudioConfig
    main_input_name = "input_features"
    input_modalities = "audio"
    _input_embed_layer = "conv1"
    _no_split_modules = ["MiniCPMO2_6AudioEncoderLayer"]
    _can_record_outputs = {
        "hidden_states": MiniCPMO2_6AudioEncoderLayer,
        "attentions": MiniCPMO2_6AudioAttention,
    }
    # The chunked attention mask can't be expressed with flash attention's padding-only masks
    _supports_flash_attn = False

    def __init__(self, config: MiniCPMO2_6AudioConfig):
        super().__init__(config)
        self.dropout = config.dropout
        self.layerdrop = config.encoder_layerdrop

        embed_dim = config.d_model
        self.num_mel_bins = config.num_mel_bins
        self.max_source_positions = config.max_source_positions
        self.embed_scale = math.sqrt(embed_dim) if config.scale_embedding else 1.0

        self.conv1 = nn.Conv1d(self.num_mel_bins, embed_dim, kernel_size=3, padding=1)
        self.conv2 = nn.Conv1d(embed_dim, embed_dim, kernel_size=3, stride=2, padding=1)

        self.embed_positions = nn.Embedding(self.max_source_positions, embed_dim)
        self.embed_positions.requires_grad_(False)
        self.layers = nn.ModuleList([MiniCPMO2_6AudioEncoderLayer(config) for _ in range(config.num_hidden_layers)])
        self.layer_norm = nn.LayerNorm(config.d_model)

        self.gradient_checkpointing = False
        # Initialize weights and apply final processing
        self.post_init()

    def _freeze_parameters(self):
        for param in self.parameters():
            param.requires_grad = False
        self._requires_grad = False

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
        self,
        input_features: torch.Tensor,
        attention_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        input_features (`torch.FloatTensor` of shape `(batch_size, num_mel_bins, num_frames)`):
            Log-mel features of up to 30 s of audio per row, as returned by [`WhisperFeatureExtractor`].
        attention_mask (`torch.Tensor` of shape `(batch_size, num_frames)`):
            Which mel frames are real (`1`) rather than padding (`0`).
        """
        # Padding frames and their conv outputs are zeroed, so each row is encoded as if it ended at its last frame
        frame_mask = attention_mask[:, None, :].to(input_features.dtype)
        inputs_embeds = nn.functional.gelu(self.conv1(input_features * frame_mask)) * frame_mask
        inputs_embeds = nn.functional.gelu(self.conv2(inputs_embeds)).permute(0, 2, 1)
        positions = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device)
        hidden_states = inputs_embeds + self.embed_positions(positions)
        hidden_states = nn.functional.dropout(hidden_states, p=self.dropout, training=self.training)

        lengths, _ = self._get_feat_extract_output_lengths(attention_mask.sum(-1))
        attention_mask = create_bidirectional_mask(
            config=self.config,
            inputs_embeds=hidden_states,
            attention_mask=torch.arange(hidden_states.shape[1], device=hidden_states.device) < lengths[:, None],
            and_mask_function=chunked_limited_mask_function(left_ctx=-1, right_ctx=self.config.chunk_size - 1),
        )
        for encoder_layer in self.layers:
            if self.training and torch.rand([]) < self.layerdrop:
                continue
            hidden_states = encoder_layer(hidden_states, attention_mask, **kwargs)

        return BaseModelOutputWithPooling(last_hidden_state=self.layer_norm(hidden_states))

    # Ignore copy
    def _get_feat_extract_output_lengths(self, input_lengths: torch.LongTensor):
        """
        Computes the output length of the convolutional layers and the output length of the audio encoder
        """
        input_lengths = (input_lengths - 1) // 2 + 1
        output_lengths = (input_lengths - 2) // 2 + 1
        return input_lengths, output_lengths


class MiniCPMO2_6AudioProjector(nn.Module):
    """
    Projects the audio encoder's frames to the language model's width, then averages each pair of frames (25 audio
    tokens per second).
    """

    def __init__(self, config: MiniCPMO2_6Config):
        super().__init__()
        self.linear_1 = nn.Linear(config.audio_config.hidden_size, config.text_config.hidden_size)
        self.act = nn.ReLU()
        self.linear_2 = nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size)

    def forward(self, audio_features: torch.Tensor) -> torch.Tensor:
        hidden_states = self.linear_2(self.act(self.linear_1(audio_features)))
        return nn.functional.avg_pool1d(hidden_states.transpose(1, 2), kernel_size=2).transpose(1, 2)


@auto_docstring(
    custom_intro="""
    The MiniCPM-o 2.6 model (vision tower and resampler, audio encoder and projector, language model), without a
    language modeling head.
    """
)
class MiniCPMO2_6Model(MiniCPMO2_6PreTrainedModel):
    def __init__(self, config: MiniCPMO2_6Config):
        super().__init__(config)
        self.vision_tower = AutoModel.from_config(config.vision_config)
        self.resampler = MiniCPMO2_6Resampler(config)
        self.language_model = AutoModel.from_config(config.text_config)
        self.audio_tower = AutoModel.from_config(config.audio_config)
        self.audio_projector = MiniCPMO2_6AudioProjector(config)
        self.post_init()

    @can_return_tuple
    @auto_docstring(custom_intro="Encodes image slices and resamples each one to `config.resampler_n_latents` tokens.")
    def get_image_features(
        self,
        pixel_values: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(num_slices, num_channels, patch_size, max_patches * patch_size)`):
            Every image slice of the batch as a single row of patches (as the checkpoint was trained), padded to the
            longest slice, as returned by [`MiniCPMV2_5ImageProcessor`].
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid, used by the vision embeddings and the resampler.
        """
        vision_outputs = self.vision_tower(
            pixel_values=pixel_values.to(self.vision_tower.dtype),
            patch_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            return_dict=True,
            **kwargs,
        )
        vision_outputs.pooler_output = self.resampler(
            vision_outputs.last_hidden_state, pixel_attention_mask, patch_position_ids
        )
        return vision_outputs

    def get_placeholder_mask(
        self, input_ids: torch.LongTensor, inputs_embeds: torch.Tensor, features: torch.Tensor, token_id: int
    ) -> torch.Tensor:
        """
        Obtains the placeholder mask of `token_id` from `input_ids` or `inputs_embeds`, and checks that the placeholder
        token count matches the number of `features`.
        """
        if input_ids is None:
            special_mask = inputs_embeds == self.get_input_embeddings()(
                torch.full((), token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_mask = special_mask.all(-1)
        else:
            special_mask = input_ids == token_id
        n_tokens = special_mask.sum()
        special_mask = special_mask.unsqueeze(-1).to(inputs_embeds.device)
        torch_compilable_check(
            n_tokens * inputs_embeds.shape[-1] == features.numel(),
            f"Multimodal features and tokens do not match, tokens: {n_tokens}, features: {features.numel() // inputs_embeds.shape[-1]}",
        )
        return special_mask

    @can_return_tuple
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_attention_mask: torch.Tensor | None = None,
        patch_position_ids: torch.Tensor | None = None,
        input_features: torch.Tensor | None = None,
        input_features_mask: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        mm_encoder_outputs: dict[str, BaseModelOutputWithPooling] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | MultimodalBaseModelOutputWithPast:
        r"""
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`, *optional*):
            Which patches of `pixel_values` are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its slice's patch grid.
        input_features_mask (`torch.Tensor` of shape `(num_windows, num_frames)`, *optional*):
            Which mel frames of `input_features` are real (`1`) rather than padding (`0`).
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")
        if pixel_values is not None and mm_encoder_outputs is not None:
            raise ValueError("You cannot specify both pixel_values and mm_encoder_outputs at the same time")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        mm_encoder_outputs = dict(mm_encoder_outputs) if mm_encoder_outputs is not None else {}
        if mm_encoder_outputs.get("image") is None and pixel_values is not None:
            mm_encoder_outputs["image"] = self.get_image_features(
                pixel_values=pixel_values,
                pixel_attention_mask=pixel_attention_mask,
                patch_position_ids=patch_position_ids,
                return_dict=True,
                **kwargs,
            )
        if mm_encoder_outputs.get("audio") is None and input_features is not None:
            mm_encoder_outputs["audio"] = self.get_audio_features(
                input_features=input_features, input_features_mask=input_features_mask, return_dict=True, **kwargs
            )

        for modality, token_id in (("image", self.config.image_token_id), ("audio", self.config.audio_token_id)):
            if mm_encoder_outputs.get(modality) is not None:
                features = mm_encoder_outputs[modality].pooler_output.to(inputs_embeds.device, inputs_embeds.dtype)
                mask = self.get_placeholder_mask(input_ids, inputs_embeds, features, token_id)
                inputs_embeds = inputs_embeds.masked_scatter(mask, features)

        outputs = self.language_model(
            attention_mask=attention_mask,
            position_ids=position_ids,
            cache=cache,
            inputs_embeds=inputs_embeds,
            **kwargs,
        )
        return MultimodalBaseModelOutputWithPast(
            **outputs, image_outputs=mm_encoder_outputs.get("image"), audio_outputs=mm_encoder_outputs.get("audio")
        )

    @can_return_tuple
    @auto_docstring(custom_intro="Encodes audio windows and projects them to 25 tokens per second of audio.")
    def get_audio_features(
        self,
        input_features: torch.Tensor,
        input_features_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        input_features (`torch.FloatTensor` of shape `(num_windows, num_mel_bins, num_frames)`):
            Log-mel features of every audio of the batch, split into windows of up to 30 s.
        input_features_mask (`torch.Tensor` of shape `(num_windows, num_frames)`):
            Which mel frames are real (`1`) rather than padding (`0`).
        """
        audio_outputs = self.audio_tower(
            input_features.to(self.audio_tower.dtype), attention_mask=input_features_mask, return_dict=True, **kwargs
        )
        audio_embeds = self.audio_projector(audio_outputs.last_hidden_state)
        _, num_tokens = self.audio_tower._get_feat_extract_output_lengths(input_features_mask.sum(-1))
        valid_mask = torch.arange(audio_embeds.shape[1], device=audio_embeds.device) < num_tokens[:, None]
        audio_outputs.pooler_output = audio_embeds[valid_mask]
        return audio_outputs


@auto_docstring(
    custom_intro="""
    The MiniCPM-o 2.6 model (vision tower and resampler, audio encoder and projector, language model) with a language
    modeling head.
    """
)
class MiniCPMO2_6ForConditionalGeneration(MiniCPMO2_6PreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.language_model.embed_tokens.weight"}
    _tp_plan = {"lm_head": "colwise_gather_output"}

    def __init__(self, config: MiniCPMO2_6Config):
        super().__init__(config)
        self.model = MiniCPMO2_6Model(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)
        self.post_init()

    def get_output_embeddings(self) -> nn.Module:
        return self.lm_head

    @auto_docstring
    def get_image_features(
        self,
        pixel_values: torch.Tensor,
        pixel_attention_mask: torch.Tensor,
        patch_position_ids: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(num_slices, num_channels, patch_size, max_patches * patch_size)`):
            Every image slice of the batch as a single row of patches, padded to the longest slice.
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`):
            Which patches are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`):
            `(row, col)` of each patch in its slice's patch grid.
        """
        return self.model.get_image_features(
            pixel_values=pixel_values,
            pixel_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            **kwargs,
        )

    @can_return_tuple
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_attention_mask: torch.Tensor | None = None,
        patch_position_ids: torch.Tensor | None = None,
        input_features: torch.Tensor | None = None,
        input_features_mask: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        labels: torch.LongTensor | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        mm_encoder_outputs: dict[str, BaseModelOutputWithPooling] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | MultimodalCausalLMOutputWithPast:
        r"""
        pixel_attention_mask (`torch.BoolTensor` of shape `(num_slices, max_patches)`, *optional*):
            Which patches of `pixel_values` are real (`True`) rather than padding.
        patch_position_ids (`torch.LongTensor` of shape `(num_slices, max_patches, 2)`, *optional*):
            `(row, col)` of each patch in its slice's patch grid.
        input_features_mask (`torch.Tensor` of shape `(num_windows, num_frames)`, *optional*):
            Which mel frames of `input_features` are real (`1`) rather than padding (`0`).

        Example:

        ```python
        >>> from transformers import AutoModelForMultimodalLM, AutoProcessor

        >>> model = AutoModelForMultimodalLM.from_pretrained("openbmb/MiniCPM-o-2_6", device_map="auto")
        >>> processor = AutoProcessor.from_pretrained("openbmb/MiniCPM-o-2_6")

        >>> messages = [
        ...     {
        ...         "role": "user",
        ...         "content": [
        ...             {"type": "text", "text": "Please listen to the audio snippet carefully and transcribe the content."},
        ...             {"type": "audio", "url": "https://huggingface.co/datasets/hf-internal-testing/dummy-audio-samples/resolve/main/bcn_weather.mp3"},
        ...         ],
        ...     }
        ... ]
        >>> inputs = processor.apply_chat_template(
        ...     messages, add_generation_prompt=True, tokenize=True, return_dict=True, return_tensors="pt"
        ... ).to(model.device)
        >>> generated = model.generate(**inputs, max_new_tokens=32)
        >>> processor.post_process_image_text_to_text(generated[:, inputs["input_ids"].shape[1] :])[0]
        ```"""
        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_attention_mask=pixel_attention_mask,
            patch_position_ids=patch_position_ids,
            input_features=input_features,
            input_features_mask=input_features_mask,
            attention_mask=attention_mask,
            position_ids=position_ids,
            cache=cache,
            inputs_embeds=inputs_embeds,
            mm_encoder_outputs=mm_encoder_outputs,
            **kwargs,
        )
        hidden_states = slice_logits_to_keep(outputs[0], logits_to_keep)
        logits = self.lm_head(hidden_states)

        loss = None
        if labels is not None:
            loss = self.loss_function(
                logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size, **kwargs
            )
        return MultimodalCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            cache=outputs.cache,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            image_outputs=outputs.image_outputs,
            audio_outputs=outputs.audio_outputs,
        )

    @auto_docstring
    def get_audio_features(
        self,
        input_features: torch.Tensor,
        input_features_mask: torch.Tensor,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        input_features (`torch.FloatTensor` of shape `(num_windows, num_mel_bins, num_frames)`):
            Log-mel features of every audio of the batch, split into windows of up to 30 s.
        input_features_mask (`torch.Tensor` of shape `(num_windows, num_frames)`):
            Which mel frames are real (`1`) rather than padding (`0`).
        """
        return self.model.get_audio_features(
            input_features=input_features, input_features_mask=input_features_mask, **kwargs
        )


